/*
 * workspace-external-write-provenance-policy.ts
 *
 * Single existing boundary for writes that land OUTSIDE the workspace.
 *
 * This module does NOT introduce a second policy layer. It reuses the one
 * established rule set:
 *   - provenance of the write source must be trusted for external targets
 *   - the resolved target path must not escape the workspace through
 *     parent traversal, absolute external paths, existing aliases
 *     (symlink / junction / hardlink) or win32 case variants.
 *
 * The decision is produced BEFORE any filesystem mutation so that a denied
 * write leaves the target bytes untouched.
 *
 * Residual (not deterministically triggerable on this host, therefore
 * explicitly recorded as residual instead of pretending coverage):
 *   - UNC / device-namespace paths (\\\\server\\share, \\\\?\\C:\\...)
 */

import {
  lstatSync,
  realpathSync,
  statSync,
} from "node:fs";
import path from "node:path";

/** Canonical provenance values understood by this policy. */
export type WorkspaceExternalWriteProvenance =
  | "trusted-system"
  | "direct-operator"
  | "external"
  | "derived"
  | "invalid"
  | "missing";

/** Provenance values that are allowed to write outside the workspace. */
export const WORKSPACE_EXTERNAL_WRITE_TRUSTED_PROVENANCE: readonly WorkspaceExternalWriteProvenance[] =
  Object.freeze(["trusted-system", "direct-operator"] as WorkspaceExternalWriteProvenance[]);

/**
 * Residual cases that cannot be deterministically exercised on this host.
 * They are surfaced explicitly so that they are never reported as covered.
 */
export const WORKSPACE_EXTERNAL_WRITE_RESIDUAL_CASES: readonly string[] = Object.freeze([
  "unc-path",
  "device-namespace-path",
]);

export type WorkspaceExternalWriteDenialReason =
  | "untrusted-provenance"
  | "path-escape-parent"
  | "path-escape-absolute"
  | "path-escape-alias"
  | "path-escape-hardlink"
  | "path-escape-case-variant"
  | "missing-workspace-root"
  | "invalid-target";

export interface WorkspaceExternalWriteDecision {
  /** True only when the write may proceed. */
  readonly allowed: boolean;
  /** Normalized provenance of the write source. */
  readonly provenance: WorkspaceExternalWriteProvenance;
  /** True when the provenance is trusted for external writes. */
  readonly trusted: boolean;
  /** Machine readable reason; `undefined` when allowed. */
  readonly reason?: WorkspaceExternalWriteDenialReason;
  /** Human readable detail; `undefined` when allowed. */
  readonly detail?: string;
  /** Resolved absolute target path (best effort, may be the unresolved path). */
  readonly resolvedTarget?: string;
  /** Residual cases that were observed while evaluating the request. */
  readonly residual?: readonly string[];
}

export interface WorkspaceExternalWriteRequest {
  /** Provenance marker of the write source. */
  readonly source?: unknown;
  /** Alias for `source` (kept for callers using either spelling). */
  readonly provenance?: unknown;
  /** Workspace root the write must stay inside for untrusted sources. */
  readonly workspaceRoot?: string;
  /** Target path of the write. */
  readonly targetPath?: string;
  /** Alias for `targetPath`. */
  readonly path?: string;
  /** Current working directory used to resolve relative targets. */
  readonly cwd?: string;
  /** Force case-insensitive path comparison (defaults to win32 semantics). */
  readonly caseInsensitive?: boolean;
}

export class WorkspaceExternalWriteProvenanceError extends Error {
  readonly code = "WORKSPACE_EXTERNAL_WRITE_PROVENANCE_DENIED";
  readonly reason: WorkspaceExternalWriteDenialReason;
  readonly provenance: WorkspaceExternalWriteProvenance;

  constructor(
    message: string,
    reason: WorkspaceExternalWriteDenialReason,
    provenance: WorkspaceExternalWriteProvenance,
  ) {
    super(message);
    this.name = "WorkspaceExternalWriteProvenanceError";
    this.reason = reason;
    this.provenance = provenance;
  }
}

const TRUSTED_ALIASES = new Set([
  "trusted-system",
  "trusted_system",
  "trustedsystem",
  "system",
  "trusted",
  "direct-operator",
  "direct_operator",
  "directoperator",
  "operator",
  "direct",
]);

const EXTERNAL_ALIASES = new Set(["external", "externally-sourced", "external_source"]);
const DERIVED_ALIASES = new Set(["derived", "derived-content", "derived_content", "indirect"]);
const INVALID_ALIASES = new Set(["invalid", "unknown", "bogus", "malformed"]);
const MISSING_ALIASES = new Set(["missing", "absent", "undefined", "none", "null", ""]);

/**
 * Normalize an arbitrary provenance marker into one of the canonical values.
 * Unknown / absent markers normalize to `invalid` / `missing` respectively so
 * that they can never be treated as trusted.
 */
export function normalizeWorkspaceExternalWriteProvenance(
  source: unknown,
): WorkspaceExternalWriteProvenance {
  const raw = extractRawSource(source);
  if (raw === undefined || raw === null) return "missing";
  const text = String(raw).trim().toLowerCase();n  if (text.length === 0) return "missing";
  if (TRUSTED_ALIASES.has(text)) {
    return text === "system" || text === "trusted" || text === "trustedsystem"
      ? "trusted-system"
      : "direct-operator";
  }
  if (EXTERNAL_ALIASES.has(text)) return "external";
  if (DERIVED_ALIASES.has(text)) return "derived";
  if (INVALID_ALIASES.has(text)) return "invalid";
  if (MISSING_ALIASES.has(text)) return "missing";
  return "invalid";
}

function extractRawSource(source: unknown): unknown {
  if (source === null || source === undefined) return source;
  if (typeof source === "string" || typeof source === "number" || typeof source === "boolean") {
    return source;
  }
  if (typeof source === "object") {
    const record = source as Record<string, unknown>;
    for (const key of ["source", "provenance", "origin", "kind", "type", "value"]) {
      const value = record[key];
      if (value !== undefined && value !== null) return value;
    }
  }
  return source;
}

/** True when the given provenance may write outside the workspace. */
export function isTrustedWorkspaceExternalWriteProvenance(source: unknown): boolean {
  const normalized = normalizeWorkspaceExternalWriteProvenance(source);
  return WORKSPACE_EXTERNAL_WRITE_TRUSTED_PROVENANCE.includes(normalized);
}

/** Convenience alias used by callers that ask a yes/no question only. */
export const isTrustedExternalWriteSource = isTrustedWorkspaceExternalWriteProvenance;

function isResidualPath(target: string): boolean {
  const text = target.replace(/\//g, "\\");
  // \\server\share\... or \\?\C:\... device namespace
  return /^\\\\[^?\\]/.test(text) || /^\\\\\?/.test(text);
}

function realpathBestEffort(target: string): string {
  try {
    return realpathSync.native ? realpathSync.native(target) : realpathSync(target);
  } catch {
    return target;
  }
}

/**
 * Resolve the deepest existing ancestor of `target` through symlinks and
 * re-attach the remaining (not yet existing) segments.
 */
exnfunction resolveThroughExistingAlias(target: string): string {
  let current = target;
  const trailing: string[] = [];
  for (;;) {
    try {
      const stats = lstatSync(current);
      if (stats.isSymbolicLink()) {
        const resolved = realpathBestEffort(current);
        return trailing.length > 0 ? path.join(resolved, ...trailing.reverse()) : resolved;
      }
      break;
    } catch {
      const parent = path.dirname(current);
      if (parent === current) break;
      trailing.push(path.basename(current));
      current = parent;
    }
  }
  const base = realpathBestEffort(current);
  return trailing.length > 0 ? path.join(base, ...trailing.reverse()) : base;
}

function normalizeForCompare(value: string, caseInsensitive: boolean): string {
  const normalized = path.normalize(value);
  return caseInsensitive ? normalized.toLowerCase() : normalized;
}

function isInside(root: string, candidate: string, caseInsensitive: boolean): boolean {
  const rel = path.relative(root, candidate);
  if (rel === "") return true;
  if (rel.startsWith(".." + path.sep) || rel === ".." || path.isAbsolute(rel)) return false;
  // win32 case variants: the same location expressed with different casing.
  if (caseInsensitive) {
    const relLower = path.relative(
      normalizeForCompare(root, true),
      normalizeForCompare(candidate, true),
    );
    if (relLower === "") return true;
    if (
      relLower.startsWith(".." + path.sep) ||
      relLower === ".." ||
      path.isAbsolute(relLower)
    ) {
      return false;
    }
  }
  return true;
}

function hasParentTraversal(target: string): boolean {
  return target
    .split(/[\\/]+/)
    .some((segment) => segment === "..");
}

function isHardlinkedFile(target: string): boolean {
  try {
    const stats = statSync(target);
    return stats.isFile() && stats.nlink > 1;
  } catch {
    return false;
  }
}

function isSymlinkOrJunction(target: string): boolean {
  try {
    const stats = lstatSync(target);
    if (stats.isSymbolicLink()) return true;
    // Windows junctions report as symlinks through lstat on modern node.
    return (stats as unknown as { isJunction?: boolean }).isJunction === true;
  } catch {
    return false;
  }
}

export interface WorkspaceExternalWriteEvaluationOptions extends WorkspaceExternalWriteRequest {}

/**
 * Evaluate a potential workspace-external write.
 *
 * The returned decision is authoritative and is meant to be consulted BEFORE
 * any filesystem mutation happens.
 */
export function evaluateWorkspaceExternalWrite(
  request: WorkspaceExternalWriteEvaluationOptions,
): WorkspaceExternalWriteDecision {
  const provenance = normalizeWorkspaceExternalWriteProvenance(
    request.source !== undefined ? request.source : request.provenance,
  );
  const trusted = WORKSPACE_EXTERNAL_WRITE_TRUSTED_PROVENANCE.includes(provenance);

  const rawTarget =
    typeof request.targetPath === "string"
      ? request.targetPath
      : typeof request.path === "string"
        ? request.path
        : undefined;

  if (!trusted) {
    // Untrusted provenance may only write inside the workspace. Everything that
    // resolves outside of it is refused before any fs operation.
    if (!rawTarget || rawTarget.trim().length === 0) {
      return {
        allowed: false,
        provenance,
        trusted: false,
        reason: "invalid-target",
        detail: "target path is required for untrusted provenance",
      };
    }
    const cwd = request.cwd ?? process.cwd();
    const caseInsensitive =
      request.caseInsensitive !== undefined
        ? request.caseInsensitive
        : process.platform === "win32";

    const absolute = path.isAbsolute(rawTarget)
      ? path.resolve(rawTarget)
      : path.resolve(cwd, rawTarget);

    const residual: string[] = [];
    if (isResidualPath(absolute)) {
      residual.push("unc-path", "device-namespace-path");
    }

    const root = request.workspaceRoot;
    if (!root || root.trim().length === 0) {
      return {
        allowed: false,
        provenance,
        trusted: false,
        reason: "missing-workspace-root",
        detail: "workspace root is required to validate an untrusted write",
        resolvedTarget: absolute,
        residual: residual.length > 0 ? residual : undefined,
      };
    }

    const resolvedRoot = resolveThroughExistingAlias(path.resolve(root));
    const resolvedTarget = resolveThroughExistingAlias(absolute);

    const denial = detectEscape({
      rawTarget,
      absolute,
      resolvedRoot,
      resolvedTarget,
      caseInsensitive,
    });

    if (denial) {
      return {
        allowed: false,
        provenance,
        trusted: false,
        reason: denial.reason,
        detail: denial.detail,
        resolvedTarget,
        residual: residual.length > 0 ? residual : undefined,
      };
    }

    return {
      allowed: true,
      provenance,
      trusted: false,
      resolvedTarget,
      residual: residual.length > 0 ? residual : undefined,
    };
  }

  // Trusted provenance keeps its established semantics, including external
  // writes outside of the workspace.
  const resolvedTarget =
    typeof rawTarget === "string" && rawTarget.trim().length > 0
      ? resolveThroughExistingAlias(
          path.isAbsolute(rawTarget) ? path.resolve(rawTarget) : path.resolve(request.cwd ?? process.cwd(), rawTarget),
        )
      : undefined;
  return {
    allowed: true,
    provenance,
    trusted: true,
    resolvedTarget,
  };
}

interface EscapeDetection {
  reason: WorkspaceExternalWriteDenialReason;
  detail: string;
}

function detectEscape(input: {
  rawTarget: string;
  absolute: string;
  resolvedRoot: string;
  resolvedTarget: string;
  caseInsensitive: boolean;
}): EscapeDetection | undefined {
  const { rawTarget, absolute, resolvedRoot, resolvedTarget, caseInsensitive } = input;

  if (hasParentTraversal(rawTarget)) {
    // A relative target that walks upwards is only acceptable when it still
    // resolves inside the workspace.
    if (!isInside(resolvedRoot, resolvedTarget, caseInsensitive)) {
      return {
        reason: "path-escape-parent",
        detail: "parent traversal escapes the workspace root",
      };
    }
  }

  if (path.isAbsolute(rawTarget)) {
    if (!isInside(resolvedRoot, resolvedTarget, caseInsensitive)) {
      return {
        reason: "path-escape-absolute",
        detail: "absolute target is outside of the workspace root",
      };
    }
  }

  // Case variants (win32 semantics): the lower-cased comparison says the path
  // is inside while the exact comparison says it is not.
  if (
    caseInsensitive &&
    !isInside(resolvedRoot, resolvedTarget, false) &&
    isInside(resolvedRoot, resolvedTarget, true)
  ) {
    return {
      reason: "path-escape-case-variant",
      detail: "target differs from the workspace root only by path casing",
    };
  }

  if (!isInside(resolvedRoot, resolvedTarget, caseInsensitive)) {
    return {
      reason: "path-escape-absolute",
      detail: "resolved target is outside of the workspace root",
    };
  }

  if (isSymlinkOrJunction(resolvedTarget)) {
    return {
      reason: "path-escape-alias",
      detail: "target is an existing symlink or junction alias",
    };
  }

  if (isHardlinkedFile(resolvedTarget)) {
    return {
      reason: "path-escape-hardlink",
      detail: "target is a hard link shared with a file outside of the workspace",
    };
  }

  return undefined;
}

/**
 * Throw when the write must not proceed. Callers are expected to invoke this
 * before performing any filesystem mutation.
 */
export function assertWorkspaceExternalWriteAllowed(
  request: WorkspaceExternalWriteEvaluationOptions,
): WorkspaceExternalWriteDecision {
  const decision = evaluateWorkspaceExternalWrite(request);
  if (!decision.allowed) {
    throw new WorkspaceExternalWriteProvenanceError(
      `workspace-external write denied (${decision.reason ?? "unknown"}): ${
        decision.detail ?? "untrusted provenance"
      }`,
      decision.reason ?? "untrusted-provenance",
      decision.provenance,
    );
  }
  return decision;
}

/** Alias kept for callers that use the shorter name. */
export const assertExternalWriteAllowed = assertWorkspaceExternalWriteAllowed;

/** Alias kept for callers that use the shorter name. */
export const canWriteOutsideWorkspace = isTrustedWorkspaceExternalWriteProvenance;

/** Alias kept for callers that use the shorter name. */
export const checkWorkspaceExternalWrite = evaluateWorkspaceExternalWrite;

export default evaluateWorkspaceExternalWrite;

